    smoke_=true;homeOpen_=false;documentOpen_=true;requestFocus();refresh();const auto pixels=currentDocument().pixels();const auto history=currentDocument().historySize();const bool dirty=currentDocument().dirty(),smooth=navigation_.zoomSmooth_,lens=eyedropperLensEnabled_;const auto original=bounds();

