    smoke_=true;homeOpen_=false;documentOpen_=true;paletteFocused_=false;currentView().frameSelection=false;currentView().maskSlots.clear();replaceDocumentForSmoke(Document(8,6));currentDocument().addFrame();currentDocument().clearTimelineSelection();
