    const bool savedHome=homeOpen_,savedOpen=documentOpen_,savedLayers=layersPanelOpen_;const int savedHomeSection=homeSection_,savedPreferenceSection=preferenceSection_,savedPreferenceNav=preferenceNavPixels_,savedPreferenceContent=preferenceContentPixels_;const double savedZoom=currentView().zoom;const auto savedPending=pending_;const auto savedError=openError_,savedTitle=errorTitle_;const auto savedModal=modalGeometry_;

