    struct Restore {std::function<void()> run;~Restore(){run();}} restore{[&]{replaceDocumentForSmoke(savedDocument);docking_=savedDock;homeEntries_=savedEntries;homeSection_=savedHomeSection;homeOpen_=savedHome;documentOpen_=savedOpen;layersPanelOpen_=savedLayers;currentView().zoom=savedZoom;currentView().canvas=savedCanvas;pending_=savedPending;openError_=savedError;errorTitle_=savedTitle;modalGeometry_=savedModal;currentView().layers=savedLayer;currentView().frames=savedFrame;currentView().layerRemainder=savedLayerRem;currentView().frameRemainder=savedFrameRem;toolRowScroll_=savedTool;railScrollPixels_=savedRail;homeScrollPixels_=savedHomePixels;errorScrollPixels_=savedErrorPixels;preferenceSection_=savedPreferenceSection;preferenceNavPixels_=savedPreferenceNav;preferenceContentPixels_=savedPreferenceContent;setBounds(savedBounds);previewPanel_->setBounds(savedPreview);refresh();}};

    auto check=[](bool okay,const char* message){if(!okay)throw std::runtime_error(message);};

    auto drag=[&](PixelScrollBar* bar,bool vertical,int distance=3){if(!bar || !bar->isVisible())throw std::runtime_error(std::string("Scrollable region has no sheet scrollbar: ")+(bar==timelineHorizontal_?"timeline horizontal":bar==timelineVertical_?"timeline vertical":bar==canvasHorizontal_?"canvas horizontal":bar==canvasVertical_?"canvas vertical":bar==railScrollBar_?"rail":bar==homeScrollBar_?"home":bar==errorScrollBar_?"error":bar==preferenceNavBar_?"preferences categories":"preferences content"));const auto thumb=bar->thumbBounds();auto pointer=thumb.center();ui::MouseMessage down(ui::kMouseDownMessage,os::PointerType::Mouse,ui::kButtonLeft,ui::kKeyNoneModifier,pointer);bar->onProcessMessage(&down);check(bar->hasCapture(),"Scrollbar thumb capture failed");pointer+=vertical?gfx::Point(0,distance):gfx::Point(distance,0);ui::MouseMessage move(ui::kMouseMoveMessage,os::PointerType::Mouse,ui::kButtonLeft,ui::kKeyNoneModifier,pointer);bar->onProcessMessage(&move);ui::MouseMessage up(ui::kMouseUpMessage,os::PointerType::Mouse,ui::kButtonLeft,ui::kKeyNoneModifier,pointer);bar->onProcessMessage(&up);check(!bar->hasCapture(),"Scrollbar capture was retained");};

    homeOpen_=false;documentOpen_=layersPanelOpen_=true;pending_=Pending::None;docking_=panels::Model{};setBounds(gfx::Rect(17,23,800,600));replaceDocumentForSmoke(Document(1,1));

    for(int i=0;i<17;++i)currentDocument().addLayer();for(int i=0;i<59;++i)currentDocument().addFrame();dockColumn(2,panels::Dock::Floating);auto& group=docking_.groups[docking_.groupOf(2)];group.floating={180,90,230,165};group.floatingArea=floatingArea(uiLogical(clientBounds()));refresh();

    currentView().layers=currentView().frames=currentView().layerRemainder=currentView().frameRemainder=0;layoutLayers();const auto history=currentDocument().historySize(),revision=currentDocument().revision();const auto oldName=layerRows_[0]->bounds(),oldHeader=frameHeaders_[0]->bounds(),oldCel=frameCells_[0]->bounds();

    drag(timelineHorizontal_,false);check(currentView().frames*timelineFrameWidth()*uiScale+currentView().frameRemainder>0,"Timeline horizontal drag did not move");check(layerRows_[0]->bounds()==oldName && frameHeaders_[0]->bounds().x<oldHeader.x && frameCells_[0]->bounds().x<oldCel.x,"Timeline horizontal scrolling moved fixed names or failed to move headers/cels");

    drag(timelineVertical_,true);check(currentView().layers*timelineRowHeight()*uiScale+currentView().layerRemainder>0 && currentView().layerRemainder!=0,"Timeline vertical drag snaps to rows");check(frameHeaders_[0]->bounds().y==oldHeader.y && layerRows_[0]->bounds().y<oldName.y,"Timeline vertical scrolling moved frame header or failed to move rows");check(currentDocument().historySize()==history && currentDocument().revision()==revision,"Timeline scroll changed document history");

    // Contract: framed tracks stop at the frame edge; timeline tracks share

