    for(auto b:frameCells_)if(b->timelineVisible){const auto visible=b->bounds()&timelineFrameViewport();if(!visible.isEmpty())check(frontWidgetAt(visible.center())==b,"Timeline partially visible cell has wrong input target");}

    docking_=panels::Model{};replaceDocumentForSmoke(Document(512,512));currentView().zoom=4;currentView().canvas=gfx::Rect(100,100,4096,4096);refresh();constrainCanvas();const auto canvasBefore=currentView().canvas;const auto viewHistory=currentDocument().historySize(),viewRevision=currentDocument().revision();drag(canvasHorizontal_,false);drag(canvasVertical_,true);check(currentView().canvas.x!=canvasBefore.x && currentView().canvas.y!=canvasBefore.y && currentDocument().historySize()==viewHistory && currentDocument().revision()==viewRevision,"Canvas scrollbar must pan without changing document");

    {const auto viewport=canvasViewport();check(canvasVertical_->bounds()==PixelScrollBar::gridBounds(viewport,true) && canvasHorizontal_->bounds()==PixelScrollBar::gridBounds(viewport,false),"Canvas scrollbar corner disagrees with timeline geometry");

      const auto content=workspaceLayout(uiLogical(clientBounds())).workspaceContent();check(canvasVertical_->bounds().x2()==toDisplay(gfx::Rect(content.x2()+1,0,1,1)).x,"Canvas scrollbar does not share the inner frame edge");}

    useGradientTool();toolRowScroll_=0;layoutToolOptions();check(canvasViewport().y==canvasFullViewport().y,"Tool options reserved an unwanted scrollbar row");commands_[1]->Click();

    setBounds(gfx::Rect(17,23,640,360));refresh();railScrollPixels_=0;layoutToolRail();drag(railScrollBar_,true);check(railScrollPixels_>0,"Small window tool rail scrollbar failed");

    setBounds(gfx::Rect(17,23,800,600));refresh();homeOpen_=true;homeSection_=2;recoveryCatalog_.beginLoad();{std::vector<project::RecoveryRecord> rows;for(int i=0;i<24;++i)rows.push_back({"scroll-"+std::to_string(i),"滚动回归","0"});recoveryCatalog_.loaded(std::move(rows));}layoutHome();drag(recentPane_->smokeScrollBar(),true);check(recentPane_->smokeScroll()>0 && recentPane_->smokeScroll()%(92*uiScale)!=0,"Home list drag still snaps to whole items");homeOpen_=false;

