void Editor::smokeHome() {

    smoke_=true;const auto saved=currentDocument();currentDocument().beginStroke({0,0},0xff112233);currentDocument().commitStroke();refresh();

    const auto pixels=currentDocument().pixels();const auto history=currentDocument().historySize();const auto identity=currentDocument().identity();

    const auto homePoint=homeButton_->bounds().center();

    if(menuBar_->getMenu()->children().front()!=homeButton_ || std::string(cursorAt(homePoint))!="progress")throw std::runtime_error("Home menu cursor or order mismatch");

    if(documentTabNew_->bounds().y2()>brushSizeInput_->bounds().y || brushSizeInput_->bounds().y2()>canvasViewport().y || brushSizeInput_->bounds().x<canvasViewport().x-Layout::inset*uiScale)throw std::runtime_error("Document tabs/options/canvas order mismatch");

    homeButton_->Click();

    if(std::string(cursorAt(homePoint))!="progress")throw std::runtime_error("Home menu lost progress cursor on home");

    if(!homeOpen_ || currentDocument().identity()!=identity || currentDocument().pixels()!=pixels || currentDocument().historySize()!=history || swatches_[0]->isVisible() || !homeReturn_->isVisible() || !documentTabNew_->isVisible() || !documentTabClose_->isVisible())throw std::runtime_error("Home switch lost project or exposed editor widgets");

    const auto dialogsBefore=newDocumentDialogCount_;const auto tabsBefore=projects_.size();homeActions_[0]->Click();

    if(pending_!=Pending::None || !homeOpen_ || currentDocument().identity()!=identity || currentDocument().pixels()!=pixels || !currentDocument().dirty() || projects_.size()!=tabsBefore || newDocumentDialogCount_!=dialogsBefore+1)throw std::runtime_error("Cancelling Home New tab dialog lost the dirty existing project");

    homeReturn_->Click();if(homeOpen_ || !swatches_[0]->isVisible() || currentDocument().pixels()!=pixels)throw std::runtime_error("Home return failed");

    replaceDocumentForSmoke(saved);refresh();showHome(true);

    const auto original=bounds();for(const auto size:{gfx::Size(720,600),gfx::Size(1280,960)}){setBounds(gfx::Rect(original.origin(),size));
      for(auto action:homeActions_)if(action->isVisible()){const auto visible=action->paletteViewport?(action->bounds()&action->paletteViewport()):action->bounds();if(visible.isEmpty()||!bounds().contains(visible))throw std::runtime_error("Home visible action escaped viewport");}
      for(auto tab:homeTabs_)if(tab->isVisible()&&!bounds().contains(tab->bounds()))throw std::runtime_error("Home visible tab escaped viewport");
      if(swatches_[0]->isVisible()||!homeAnnouncements_||!bounds().contains(homeAnnouncements_->bounds()))throw std::runtime_error("Home resize escaped viewport");
      homeAnnouncements_->scrollEnd();for(auto action:homeActions_)if(action->isVisible()&&action->paletteViewport){const auto visible=action->bounds()&action->paletteViewport();if(visible.isEmpty()||!bounds().contains(visible))throw std::runtime_error("Home scrolled action escaped viewport");}
    }

    setBounds(original);refresh();

  }

void Editor::smokeMenuPointerOwnership(){

    smoke_=true;homeOpen_=false;documentOpen_=true;setBounds({0,0,1280,960});currentTools().selectionTool=true;currentTools().selectionKind=0;replaceDocumentForSmoke(Document(32,32));refresh();

    PixelMenu menu(skin_);auto item=new PixelMenuItem(font_,skin_,U"菜单命中检查");menu.addChild(item);

    auto disabled=new PixelMenuItem(font_,skin_,U"禁用项也遮挡背景");disabled->setEnabled(false);menu.addChild(disabled);

    bool checked=false;std::string failure;

    ui::Timer verify(80,&menu);verify.Tick.connect([&]{

      try{

        for(auto target:{item,disabled}){

          const auto at=target->bounds().center();const auto screen=target->display()->nativeWindow()->pointToScreen(at);

          if(manager()->pickFromScreenPos(screen)!=target)throw std::runtime_error("Menu lost hit priority to background");

          ui::MouseMessage down(ui::kMouseDownMessage,os::PointerType::Mouse,ui::kButtonLeft,ui::kKeyNoneModifier,at);down.setDisplay(target->display());down.setFromFilter(true);

          if(manager()->sendMessage(&down))throw std::runtime_error("Background filter consumed menu press");

          if(onProcessMessage(&down)||panelHasCapture()||selectionDragging_)throw std::runtime_error("Menu press leaked into background gesture");

          const auto local=display()->nativeWindow()->pointFromScreen(screen);updatePaletteMouse(local);

          if(selectionPointerVisible(local)||!selectionPointerDamage_.isEmpty())throw std::runtime_error("Selection feedback leaked through menu");

        }

        checked=true;

      }catch(const std::exception& e){failure=e.what();}

      verify.stop();menu.window()->closeWindow(nullptr);

    });verify.start();menu.showPopup(canvasViewport().center(),display());

    if(!failure.empty())throw std::runtime_error(failure);

    if(!checked)throw std::runtime_error("Menu ownership check did not run");

  }

