    if(selectionDragging_||hasCapture()||currentDocument().historySize()!=history)throw std::runtime_error("Selection tool consumed overlay click");

    overlay->setVisible(false);removeChild(overlay);delete overlay;

    eyedropperHeld_=true;refreshCanvasPointerFeedback();

    if(selectionPointerVisible(pointer)||!selectionPointerDamage_.isEmpty()||std::string(cursorAt(pointer))!="eyedropper")throw std::runtime_error("Selection pointer conflicts with eyedropper");

    eyedropperHeld_=false;spaceHeld_=true;refreshCanvasPointerFeedback();

    if(selectionPointerVisible(pointer)||std::string(cursorAt(pointer))!="grab")throw std::runtime_error("Selection pointer conflicts with pan");

