void Editor::smokeAnts(const std::filesystem::path& output) {

    smoke_=true;replaceDocumentForSmoke(Document(32,24));currentDocument().previewSelection(SelectionMask{2,2,24,16,{}});

    const gfx::Rect area(0,0,320,240),cv(8,8,256,192);const auto history=currentDocument().historySize();

    for(double scale:{.5,1.0,2.0,8.0}) {

      currentView().zoom=scale/uiScale;

      auto render=[&](int phase){auto surface=os::instance()->makeRgbaSurface(area.w,area.h);surface->clear();ui::Graphics g(surface);paintSelectionAnts(g,cv,area,phase);return surface;};

      auto first=render(0),inverse=render(4),cycle=render(8);

      const int y=int(cv.y+2*scale),left=int(cv.x+2*scale);int changes=0;

      for(int x=left+2;x<left+int(24*scale)-2;++x) {

        const auto a=first->getPixel(x,y),b=inverse->getPixel(x,y);

        if(a!=gfx::rgba(0,0,0,255) && a!=gfx::rgba(255,255,255,255))throw std::runtime_error("Ants stroke is not opaque black/white");

        if(a==b || a!=cycle->getPixel(x,y))throw std::runtime_error("Ants phase inversion/cycle failed");

        if(a!=first->getPixel(x-1,y))++changes;

        if(first->getPixel(x,y+1)!=0)throw std::runtime_error("Ants stroke exceeded one device pixel");

      }

      if(changes<1)throw std::runtime_error("Ants pattern scaled with document pixels");

      if(scale==8)writeSmokeFrame(first.get(),output/"ants-smoke.bmp");

    }

    SelectionMask hole{2,2,12,12,std::vector<unsigned char>(144,1)};

    for(int y=4;y<8;++y)for(int x=4;x<8;++x)hole.mask[y*12+x]=0;

    currentDocument().previewSelection(hole);currentView().zoom=2.0/uiScale;

    auto surface=os::instance()->makeRgbaSurface(area.w,area.h);surface->clear();

    {ui::Graphics g(surface);paintSelectionAnts(g,cv,area,0);}

    if(surface->getPixel(cv.x+14,cv.y+12)==0 || surface->getPixel(cv.x+14,cv.y+14)!=0)throw std::runtime_error("Ants hole boundary failed");

    if(currentDocument().historySize()!=history || currentDocument().dirty())throw std::runtime_error("Ants rendering mutated document");

    // Compare the production merged/cache path with the original unit-edge
    // renderer, including fractional zoom, clipped/negative origins and phases.
    for(bool fragmented:{false,true}){
      auto selected=hole;if(fragmented)for(int y=0;y<selected.height;++y)for(int x=0;x<selected.width;++x)selected.mask[y*selected.width+x]=((x+y)%3)==0;
      currentDocument().previewSelection(selected);
      for(double scale:{.5,.75,1.0,2.0,8.0})for(const auto origin:{gfx::Point(8,8),gfx::Point(-12,-9)})for(int phase:{0,3,4}){
        currentView().zoom=scale/uiScale;const gfx::Rect placed(origin.x,origin.y,256,192);
        auto actual=os::instance()->makeRgbaSurface(area.w,area.h),reference=os::instance()->makeRgbaSurface(area.w,area.h);actual->clear();reference->clear();
        {ui::Graphics g(actual);paintSelectionAnts(g,placed,area,phase);}
        gfx::Path path;auto line=[&](int x,int y,int x2,int y2){path.moveTo(placed.x+x*scale,placed.y+y*scale);path.lineTo(placed.x+x2*scale,placed.y+y2*scale);};
        const auto& s=currentDocument().selection();
        for(int y=std::max(s->y,int(std::floor((area.y-placed.y)/scale))-1);y<std::min(s->y+s->height,int(std::ceil((area.y2()-placed.y)/scale))+1);++y)
          for(int x=std::max(s->x,int(std::floor((area.x-placed.x)/scale))-1);x<std::min(s->x+s->width,int(std::ceil((area.x2()-placed.x)/scale))+1);++x)if(selectionContains(s,x,y)){
            if(!selectionContains(s,x,y-1))line(x,y,x+1,y);if(!selectionContains(s,x,y+1))line(x,y+1,x+1,y+1);
            if(!selectionContains(s,x-1,y))line(x,y,x,y+1);if(!selectionContains(s,x+1,y))line(x+1,y,x+1,y+1);
          }
        {ui::Graphics g(reference);ui::Paint paint;paint.style(ui::Paint::Stroke);ui::set_checkered_paint_mode(paint,phase,gfx::rgba(0,0,0,255),gfx::rgba(255,255,255,255));g.drawPath(path,paint);}
        for(int y=0;y<area.h;++y)for(int x=0;x<area.w;++x)if(actual->getPixel(x,y)!=reference->getPixel(x,y))throw std::runtime_error("Cached ants differ from original pixel render at scale="+std::to_string(scale)+" x="+std::to_string(x)+" y="+std::to_string(y));
      }
    }
    currentDocument().previewSelection(hole);currentView().zoom=2.0/uiScale;

    const auto beforeSelection=currentDocument().selection();const auto beforePixels=currentDocument().pixels();const auto beforeRevision=currentDocument().revision();

    if(!menuCommands_.invoke("toggleSelectionOutline") || currentView().showSelectionOutline || !menuCommands_.checked("toggleSelectionOutline"))throw std::runtime_error("Outline menu hide");

    surface->clear();{ui::Graphics g(surface);paintSelectionAnts(g,cv,area,0);}for(int y=0;y<area.h;++y)for(int x=0;x<area.w;++x)if(surface->getPixel(x,y)!=0)throw std::runtime_error("Hidden outline still rendered");

    if(!selectionEqual(beforeSelection,currentDocument().selection()) || currentDocument().pixels()!=beforePixels || currentDocument().historySize()!=history || currentDocument().dirty() || currentDocument().revision()!=beforeRevision)throw std::runtime_error("Outline toggle mutated document");

    ui::KeyMessage show(ui::kKeyDownMessage,ui::kKeyH,ui::kKeyCtrlModifier,0,0);onProcessMessage(&show);if(!currentView().showSelectionOutline)throw std::runtime_error("Outline Ctrl+H show");

    ui::KeyMessage repeated(ui::kKeyDownMessage,ui::kKeyH,ui::kKeyCtrlModifier,0,1);onProcessMessage(&repeated);if(!currentView().showSelectionOutline)throw std::runtime_error("Outline key repeat toggled view");

    replaceDocumentForSmoke(Document(3,1));currentDocument().beginStroke({0,0},0xff123456);currentDocument().commitStroke();currentDocument().commitSelection({},SelectionMask{0,0,1,1,{}});refresh();currentDocument().markSaved();const auto floatingHistory=currentDocument().historySize();if(!currentDocument().nudgeSelectionContent(1,0))throw std::runtime_error("Outline floating fixture");

    menuCommands_.invoke("toggleSelectionOutline");if(currentView().showSelectionOutline || !currentDocument().floating() || currentDocument().pixels()[1]!=0xff123456 || currentDocument().historySize()!=floatingHistory || currentDocument().dirty())throw std::runtime_error("Outline hide committed floating selection");menuCommands_.invoke("toggleSelectionOutline");if(!currentDocument().floating() || currentDocument().pixels()[1]!=0xff123456)throw std::runtime_error("Outline show stale floating pixels");currentDocument().cancelFloatingPaste();

    menuCommands_.invoke("toggleSelectionOutline");bindProjectDocument(std::make_shared<Document>(2,1));refresh();if(!currentView().showSelectionOutline)throw std::runtime_error("New document outline default");if(menuCommands_.enabled("toggleSelectionOutline"))throw std::runtime_error("Outline menu without selection enabled");

  }

void Editor::smokeModalComponents() {
    smoke_=true;homeOpen_=false;documentOpen_=true;setBounds({0,0,1280,960});refresh();
    const auto pixels=currentDocument().pixels();const auto history=currentDocument().historySize();std::string spacingErrors;
    for(auto kind:{Pending::LayerOpacity,Pending::FrameDuration,Pending::LoopSection,Pending::PaletteName,Pending::PaletteLibrary,Pending::PaletteSave,Pending::PaletteExtract,Pending::ColorAdjustment,Pending::Convolution,Pending::AntiAlias,Pending::ReplaceColor,Pending::ImageResize,Pending::BrushFolderName,Pending::StaticExport,Pending::SpriteSheet,Pending::GifExport,Pending::SheetImport,Pending::Preferences}){
      pending_=kind;modalGeometry_.erase(kind);refresh();
      const auto initial=dialogDisplayBounds();
      for(int edges:{1,2,4,8,5,6,9,10}){
        const gfx::Point point(edges&1?initial.x+1:edges&2?initial.x2()-1:initial.center().x,edges&4?initial.y+1:edges&8?initial.y2()-1:initial.center().y);
        if(std::string(cursorAt(point))!=panelResizeCursor(edges))throw std::runtime_error("Modal component edge cursor");
        if(std::string(cursorAt(initial.center()))!="default" || std::string(cursorAt(initial.origin()-gfx::Point(2,2)))!="default")throw std::runtime_error("Modal component cursor not reset");
      }
      modalGeometry_[kind]={10,20,1,1};layoutModal();const auto floor=modalMinimumSize();const auto fitted=modalBounds(uiLogical(clientBounds()));
      if(fitted.w<floor.w || fitted.h<floor.h || !dialogDisplayBounds().contains(keep_->bounds()))throw std::runtime_error("Modal component saved content floor kind="+std::to_string(int(kind))+" min="+std::to_string(floor.w)+","+std::to_string(floor.h)+" actual="+std::to_string(fitted.w)+","+std::to_string(fitted.h)+" footer="+std::to_string(keep_->bounds().x)+","+std::to_string(keep_->bounds().y)+","+std::to_string(keep_->bounds().w)+","+std::to_string(keep_->bounds().h));
      const auto area=dialogDisplayBounds();const int footerTop=modalActionY(fitted)*uiScale+bounds().y;
      if(area.y2()-keep_->bounds().y2()!=UiSpacing::padding*uiScale)spacingErrors+="Footer padding kind="+std::to_string(int(kind))+"; ";
      for(auto child:children())if(modalControl(child)&&!child->hasFlags(ui::HIDDEN)&&child!=dialogClose_&&child!=keep_&&child!=discard_&&child!=saveBeforeClose_&&child!=preferenceApply_){
        if(auto button=dynamic_cast<PixelButton*>(child))if(button->paletteViewport)continue;
        if(auto entry=dynamic_cast<PixelEntry*>(child))if(entry->paletteViewport)continue;
        if(dynamic_cast<PixelScrollBar*>(child))continue;
        const auto box=child->bounds();if(box.y==footerTop && box.h==textControlHeight*uiScale){if(!area.contains(box))spacingErrors+="Footer width kind="+std::to_string(int(kind))+"; ";continue;}
        if(box.w && box.h && (!area.contains(box)||box.y<area.y+DialogLayout::bodyTop*uiScale||box.y2()>footerTop-UiSpacing::group*uiScale)){
          auto button=dynamic_cast<PixelButton*>(child);spacingErrors+="Modal body spacing kind="+std::to_string(int(kind))+" control="+(button?utf8Text(button->caption):"field")+" box="+std::to_string(box.x-area.x)+","+std::to_string(box.y-area.y)+","+std::to_string(box.w)+","+std::to_string(box.h)+" footer="+std::to_string(footerTop-area.y)+"; ";
        }
      }
      if(kind==Pending::StaticExport||kind==Pending::Preferences||kind==Pending::LayerOpacity){auto image=os::instance()->makeRgbaSurface(bounds().w,bounds().h);image->clear();{ui::Graphics g(image);ui::PaintEvent event(this,&g);onPaint(event);paintDialog(g);}for(auto child:children())if(!child->hasFlags(ui::HIDDEN)&&modalControl(child)){ui::Graphics g(nullptr,image,child->bounds().x,child->bounds().y);g.saveClip();g.clipRect(child->clientBounds());ui::PaintEvent ev(child,&g);if(auto button=dynamic_cast<PixelButton*>(child))button->onPaint(ev);else if(auto entry=dynamic_cast<PixelEntry*>(child))entry->onPaint(ev);else if(auto slider=dynamic_cast<PixelSlider*>(child))slider->onPaint(ev);g.restoreClip();}writeSmokeFrame(image.get(),assets_.parent_path()/("ui-spacing-"+std::to_string(int(kind))+".bmp"));}
      const auto before=dialogDisplayBounds();const gfx::Point edge(before.x2()-1,before.y2()-1);
      for(auto type:{ui::kMouseDownMessage,ui::kMouseMoveMessage,ui::kMouseUpMessage}){
        ui::MouseMessage msg(type,os::PointerType::Mouse,ui::kButtonLeft,ui::kKeyNoneModifier,type==ui::kMouseDownMessage?edge:edge+gfx::Point(-10000,-10000));onProcessMessage(&msg);
      }
      if(hasCapture() || std::string(cursorAt(dialogDisplayBounds().center()))!="default")throw std::runtime_error("Modal component capture/cursor after resize");
      const auto result=modalBounds(uiLogical(clientBounds()));if(result.w<floor.w || result.h<floor.h)throw std::runtime_error("Modal component drag crossed content floor");
    }
    if(!spacingErrors.empty())throw std::runtime_error(spacingErrors);
    pending_=Pending::None;currentTools().selectionTool=true;layoutToolOptions();
    for(auto button:selectionModeButtons_)if(button->bounds().size()!=gfx::Size(propertyIconWidth*uiScale,propertyIconHeight*uiScale) || button->bounds().y!=symmetryButtons_[0]->bounds().y)throw std::runtime_error("Selection mode and mirror button size/alignment mismatch");
    if(currentDocument().pixels()!=pixels || currentDocument().historySize()!=history)throw std::runtime_error("Dialog geometry changed document");
  }

void Editor::smokeWorkspace() {
    const bool modalLayoutOnly=std::wstring(GetCommandLineW()).find(L"--workspace-modal-layout-only")!=std::wstring::npos;
    if(std::wstring(GetCommandLineW()).find(L"--replace-cell-selection-only")!=std::wstring::npos){smokeColorReplacement();return;}
    if(!modalLayoutOnly&&std::wstring(GetCommandLineW()).find(L"--named-workspace-only")!=std::wstring::npos){smoke_=true;homeOpen_=false;documentOpen_=true;smokeNamedWorkspacePresets();return;}

    smoke_=true;dockWidth_=0;paletteShare_=0;timelineHeight_=109;modalGeometry_.clear();
    if(!modalLayoutOnly)smokeNamedWorkspacePresets();
    // Preset restoration can install managed docking; the following legacy
    // preview fixture dispatches directly to the standalone preview widget.
    historyPanelOpen_=false;docking_=panels::Model{};previewPanelOpen_=true;palettePanelOpen_=colorPickerOpen_=layersPanelOpen_=true;previewPanel_->setBounds(gfx::Rect(bounds().x+400,bounds().y+180,360,240));refresh();

    smokePointerPopup();

    const auto pixels=currentDocument().pixels();const auto history=currentDocument().historySize();const auto dirty=currentDocument().dirty();

    const auto original=bounds();const auto scale=currentView().zoom;

    for(int i=0;i<4;++i)if(topActions_[i]->bounds().w!=textControlHeight*uiScale || topActions_[i]->bounds().h!=textControlHeight*uiScale || topActions_[i]->bounds().y<bounds().y || topActions_[i]->bounds().y2()>bounds().y+Layout::menuHeight*uiScale)throw std::runtime_error("Top action dimensions");

    for(const auto size:{gfx::Size(720,600),gfx::Size(1280,960),gfx::Size(1600,1000)}) {

      setBounds(gfx::Rect(original.x,original.y,size.w,size.h));refresh();

      const auto dock=paletteContentBounds(),picker=colorPicker_->bounds(),view=canvasViewport();

      if(dock.x<=toolRail_[0]->bounds().x2() || dock.x2()>=view.x || picker.x<=toolRail_[0]->bounds().x2() || picker.x2()>=view.x)

        throw std::runtime_error("Color panels are not between tool rail and canvas");

      if(!bounds().contains(previewPanel_->bounds()) || !previewPanel_->isVisible() || !swatches_[0]->isVisible())

        throw std::runtime_error("Floating preview hides palette or exceeds workspace");

    }

    setBounds(original);refresh();const auto initial=previewPanel_->bounds();

    auto mouse=[&](ui::MessageType type,gfx::Point point) {

      ui::MouseMessage event(type,os::PointerType::Mouse,ui::kButtonLeft,ui::kKeyNoneModifier,point);

      previewPanel_->onProcessMessage(&event);

    };

    const gfx::Point header(initial.x+20,initial.y+12);

    if(std::string(cursorAt(header))!="move")throw std::runtime_error("Preview title did not use legacy move cursor");

    mouse(ui::kMouseDownMessage,header);

    if(std::string(cursorAt(header))!="move")throw std::runtime_error("Preview dragging did not use legacy move cursor");

    mouse(ui::kMouseUpMessage,header);

    mouse(ui::kMouseDownMessage,header);mouse(ui::kMouseMoveMessage,header+gfx::Point(-40,-30));mouse(ui::kMouseUpMessage,header+gfx::Point(-40,-30));

    if(previewPanel_->bounds().origin()!=initial.origin()+gfx::Point(-40,-30))throw std::runtime_error("Preview title drag failed");

    const auto moved=previewPanel_->bounds();const gfx::Point corner(moved.x2()-2,moved.y2()-2);

    mouse(ui::kMouseDownMessage,corner);mouse(ui::kMouseMoveMessage,corner+gfx::Point(20,20));mouse(ui::kMouseUpMessage,corner+gfx::Point(20,20));

    const auto resized=previewPanel_->bounds();

    if(resized.w!=moved.w+20 || resized.h!=moved.h+20)throw std::runtime_error("Preview corner resize failed");

    previewPanel_->closePanel();if(previewPanelOpen_ || previewPanel_->isVisible())throw std::runtime_error("Preview close failed");

    menuCommands_.invoke("togglePreviewPanel");

    if(!previewPanel_->isVisible() || previewPanel_->bounds()!=resized || !swatches_[0]->isVisible())throw std::runtime_error("Preview reopen lost geometry or palette");

    docking_=panels::Model{};previewPanel_->setBounds(resized);refresh();
    const auto preciseStart=previewPanel_->bounds();const gfx::Point preciseHeader(preciseStart.x+20,preciseStart.y+12);

    mouse(ui::kMouseDownMessage,preciseHeader);mouse(ui::kMouseMoveMessage,preciseHeader+gfx::Point(9,0));flushPanelGeometry();

    if(previewPanel_->bounds().x!=preciseStart.x+9)throw std::runtime_error("Preview drag quantized device-pixel position before="+std::to_string(preciseStart.x)+","+std::to_string(preciseStart.y)+" after="+std::to_string(previewPanel_->bounds().x)+","+std::to_string(previewPanel_->bounds().y)+" capture="+std::to_string(previewPanel_->hasCapture())+" managed="+std::to_string(previewPanel_->managed));

    mouse(ui::kMouseMoveMessage,preciseHeader+gfx::Point(10,0));flushPanelGeometry();

    if(previewPanel_->bounds().x!=preciseStart.x+10)throw std::runtime_error("Preview one-pixel continuation failed");

    mouse(ui::kMouseUpMessage,preciseHeader+gfx::Point(10,0));

    auto drag=[&](gfx::Point point,gfx::Point delta) {

      const auto count=sizeLayoutUpdates_;

      for(int i=0;i<=201;++i) {

        const auto type=i==0?ui::kMouseDownMessage:i==201?ui::kMouseUpMessage:ui::kMouseMoveMessage;

        const auto at=point+gfx::Point(delta.x*std::min(i,200)/200,delta.y*std::min(i,200)/200);

        ui::MouseMessage event(type,os::PointerType::Mouse,ui::kButtonLeft,ui::kKeyNoneModifier,at);

        onProcessMessage(&event);

        if(i<=200 && sizeLayoutUpdates_!=count)throw std::runtime_error("Resize burst performed redundant layout before frame flush");

      }

      if(sizeLayoutUpdates_>count+1)throw std::runtime_error("Resize burst was not coalesced");

      if(hasCapture() || sizeDrag_!=SizeDrag::None)throw std::runtime_error("Resize capture did not release");

    };

    auto l=workspaceLayout(uiLogical(bounds()));

    gfx::Point edge((l.rightX+l.right)*uiScale,(l.top+10)*uiScale);

    if(std::string(cursorAt(edge))!="ew-resize")throw std::runtime_error("Dock resize cursor missing");

    {

      const auto oldControl=brushShapeButton_->bounds();const auto updates=sizeLayoutUpdates_;

      ui::MouseMessage down(ui::kMouseDownMessage,os::PointerType::Mouse,ui::kButtonLeft,ui::kKeyNoneModifier,edge);onProcessMessage(&down);

      for(int dx:{10,20,30}){

        ui::MouseMessage move(ui::kMouseMoveMessage,os::PointerType::Mouse,ui::kButtonLeft,ui::kKeyNoneModifier,edge+gfx::Point(dx,0));onProcessMessage(&move);flushPanelGeometry();

        if(!hasCapture() || brushShapeButton_->bounds().x!=oldControl.x+dx)throw std::runtime_error("Held dock resize did not move tool properties with canvas");

        const auto layout=workspaceLayout(uiLogical(bounds()));if(commands_[4]->bounds().x2()!=(layout.workX+layout.workW)*uiScale)throw std::runtime_error("Held dock resize lost undo/redo canvas alignment");

      }

      ui::MouseMessage up(ui::kMouseUpMessage,os::PointerType::Mouse,ui::kButtonLeft,ui::kKeyNoneModifier,edge);onProcessMessage(&up);

      if(brushShapeButton_->bounds()!=oldControl || sizeLayoutUpdates_>updates+4)throw std::runtime_error("Dock resize property restore/coalescing failed");

    }

    drag(edge,gfx::Point(40,0));if(workspaceLayout(uiLogical(bounds())).right!=l.right+20)throw std::runtime_error("Left dock width resize failed");

    l=workspaceLayout(uiLogical(bounds()));edge=gfx::Point((l.rightX+10)*uiScale,l.split*uiScale);

    if(std::string(cursorAt(edge))!="ns-resize")throw std::runtime_error("Panel divider cursor missing");

    drag(edge,gfx::Point(0,40));if(workspaceLayout(uiLogical(bounds())).split!=l.split+20)throw std::runtime_error("Color panel split resize failed");

    l=workspaceLayout(uiLogical(bounds()));edge=gfx::Point((l.workX+10)*uiScale,l.layerTop*uiScale);

    drag(edge,gfx::Point(0,-40));if(workspaceLayout(uiLogical(bounds())).layerTop!=l.layerTop-20)throw std::runtime_error("Timeline resize failed");

    showLayerOpacity();

    for(int edges:{1,2,4,8,5,6,9,10}) {

      const auto before=dialogDisplayBounds();

      const gfx::Point at(edges&1?before.x+2:edges&2?before.x2()-2:before.x+before.w/2,

                          edges&4?before.y+2:edges&8?before.y2()-2:before.y+before.h/2);

      const gfx::Point delta(edges&1?-20:edges&2?20:0,edges&4?-20:edges&8?20:0);

      if(std::string(cursorAt(at))!=panelResizeCursor(edges))throw std::runtime_error("Modal resize cursor mismatch edges="+std::to_string(edges)+" actual="+cursorAt(at)+" gesture="+std::to_string(panelGesture_.id)+" size="+std::to_string(int(sizeDrag_))+" pending="+std::to_string(int(pending_)));

      drag(at,delta);const auto after=dialogDisplayBounds();
      if(std::string(cursorAt(after.center()))!="default" || std::string(cursorAt(after.origin()-gfx::Point(4*uiScale,4*uiScale)))!="default")throw std::runtime_error("Modal edge cursor remained outside edge");

      if((edges&1 && after.x2()!=before.x2()) || (edges&2 && after.x!=before.x) ||

         (edges&4 && after.y2()!=before.y2()) || (edges&8 && after.y!=before.y))throw std::runtime_error("Modal resize lost opposite anchor");

      if((edges&3 && after.w!=before.w+20) || (edges&12 && after.h!=before.h+20))throw std::runtime_error("Modal edge failed to resize: "+std::to_string(edges)+" before "+std::to_string(before.w)+","+std::to_string(before.h)+" after "+std::to_string(after.w)+","+std::to_string(after.h));

      if(!after.contains(keep_->bounds()) || !after.contains(layerOpacityRange_->bounds()))throw std::runtime_error("Resized modal controls escaped frame");

    }

    auto modal=dialogDisplayBounds();

    drag(gfx::Point(modal.x+2,modal.y+modal.h/2),gfx::Point(modal.w-40*uiScale,0));

    if(modalBounds(uiLogical(bounds())).w!=modalMinimumSize().w)throw std::runtime_error("Modal content width floor");

    const auto footer=keep_->bounds(),opacityBefore=layerOpacityRange_->bounds();modal=dialogDisplayBounds();

    drag(gfx::Point(modal.x2()-2,modal.y2()-2),gfx::Point(40,40));

    if(keep_->bounds().y!=footer.y+40 || layerOpacityRange_->bounds().w!=opacityBefore.w+40 || layerOpacityRange_->bounds().x-dialogDisplayBounds().x!=6*uiScale || dialogDisplayBounds().x2()-layerOpacityRange_->bounds().x2()!=6*uiScale)throw std::runtime_error("Dialog controls did not reflow");

    const auto savedModals=modalGeometry_;const auto savedPreview=previewPanel_->bounds();

    std::stringstream preferences;writeWorkspaceSizes(preferences);

    const auto savedWidth=dockWidth_,savedHeight=timelineHeight_;const auto savedShare=paletteShare_;

    dockWidth_=0;timelineHeight_=109;paletteShare_=0;modalGeometry_.clear();readWorkspaceSizes(preferences);

    if(dockWidth_!=savedWidth || timelineHeight_!=savedHeight || paletteShare_!=savedShare || modalGeometry_!=savedModals || previewPanel_->bounds()!=savedPreview)

      throw std::runtime_error("Workspace size preferences roundtrip failed dock="+std::to_string(dockWidth_==savedWidth)+" height="+std::to_string(timelineHeight_==savedHeight)+" share="+std::to_string(paletteShare_==savedShare)+" modals="+std::to_string(modalGeometry_==savedModals)+" preview="+std::to_string(previewPanel_->bounds()==savedPreview)+" encoded="+preferences.str());

    std::istringstream invalid("moonsprite-workspace-sizes-v1\ndock -1 2 -1\nmodal layer-opacity 0 0 -1 -1\n");readWorkspaceSizes(invalid);

    if(dockWidth_!=savedWidth || modalGeometry_!=savedModals)throw std::runtime_error("Invalid layout preference replaced valid sizes");

    resolve(false);

    const auto previousError=openError_;const auto previousTitle=errorTitle_;

    std::string longError;for(int i=0;i<80;++i)longError+="A long path or import error must remain readable.\n";

    showSaveError(std::runtime_error(longError));

    std::u32string joined;for(const auto& line:modalErrorLines(220))joined+=line;

    auto expected=openError_;expected.erase(std::remove(expected.begin(),expected.end(),U'\n'),expected.end());

    if(joined!=expected)throw std::runtime_error("Modal wrapping lost error text");

    for(const auto size:{gfx::Size(720,600),gfx::Size(1600,1000)}) {

      setBounds(gfx::Rect(original.x,original.y,size.w,size.h));modalGeometry_.erase(Pending::OpenError);layoutModal();

      const auto area=uiLogical(bounds());const auto fitted=modalBounds(area);

      if(!area.contains(fitted) || fitted.h>area.h*3/4 || !uiPhysical(fitted).contains(keep_->bounds()) || keep_->bounds().center().x!=uiPhysical(fitted).center().x)

        throw std::runtime_error("Adaptive dialog or centered footer failed");

      ui::MouseMessage wheel(ui::kMouseWheelMessage,os::PointerType::Mouse,ui::kButtonNone,ui::kKeyNoneModifier,uiPhysical(fitted).center(),gfx::Point(0,10000));

      onProcessMessage(&wheel);

      if(modalErrorScroll_!=int(modalErrorLines(fitted.w-20).size())-modalErrorVisibleLines(fitted))throw std::runtime_error("Error overflow cannot reach last line");

      modalGeometry_[Pending::OpenError]=gfx::Rect(-200,-200,3000,3000);layoutModal();

      if(!area.contains(modalBounds(area)))throw std::runtime_error("Saved oversized dialog escaped small window");

    }

    resolve(false);openError_=previousError;errorTitle_=previousTitle;modalGeometry_.erase(Pending::OpenError);setBounds(original);refresh();

    if(currentDocument().pixels()!=pixels || currentDocument().historySize()!=history || currentDocument().dirty()!=dirty || currentView().zoom!=scale)

      throw std::runtime_error("Workspace interactions changed document or canvas scale");

    // Geometry framebuffer comparisons require stable canvas overlays. The
    // brush preview depends on live OS hover/capture even when the synthetic
    // panel gesture leaves the document unchanged; brush overlays are checked
    // independently by smokeBrushPreview/brush-preview-performance.
    useMoveTool();
    docking_=panels::Model{};previewPanelOpen_=true;refresh();
    invalidate();

  }

void Editor::smokePointerPopup() {

    const auto native=display()->nativeWindow();const auto originalFrame=native->frame();

    auto restore=[&]{native->setFrame(originalFrame);};

    try {

      for(const auto origin:{gfx::Point(137,93),gfx::Point(-40,120)}) {

        auto frame=originalFrame;frame.x=origin.x;frame.y=origin.y;native->setFrame(frame);

        for(bool edge:{false,true}) {

          const auto area=display()->bounds();

          const gfx::Point local=edge?gfx::Point(area.x2()-3,area.y2()-3):gfx::Point(100,110);

          const auto screen=native->pointToScreen(local);const auto anchor=pointerMenuPosition(screen);

          if(anchor!=local)throw std::runtime_error("Pointer popup screen/display conversion failed");

          PixelMenu menu(skin_);buildColumnContextMenu(menu,Column::Palette);

          gfx::Rect opened;ui::Timer closeTimer(20,this);

          closeTimer.Tick.connect([&]{closeTimer.stop();menu.window()->closeWindow(this);});

          menu.OpenPopup.connect([&]{opened=menu.window()->bounds();closeTimer.start();});

          menu.showPopup(anchor,display());

          if(opened.isEmpty() || !area.contains(opened))throw std::runtime_error("Pointer popup escaped parent display");

          // Aseprite choose_side overlaps the horizontal anchor by one UI

          // scale unit; retain that fitting behavior while rejecting offsets.

          if(!edge && (std::abs(opened.x-local.x)>uiScale || opened.y!=local.y))throw std::runtime_error("Pointer popup did not open beside pointer in moved window: "+std::to_string(opened.x)+","+std::to_string(opened.y)+" expected near "+std::to_string(local.x)+","+std::to_string(local.y));

        }

      }

      restore();

    }catch(...){restore();throw;}

  }

