void Editor::smokeBrushPreview(){

    // A brush-input fixture requires an unobstructed canvas.
    previewPanelOpen_=false;
    smoke_=true;setBounds(gfx::Rect(0,0,1280,960));replaceDocumentForSmoke(Document(16,12));documentOpen_=true;homeOpen_=false;pending_=Pending::None;

    currentTools().selectionTool=currentTools().shapeTool=currentTools().gradientTool=currentTools().fillTool=currentTools().handTool=currentTools().zoomTool=currentTools().eyedropperTool=currentTools().eraser=spaceHeld_=eyedropperHeld_=false;currentPlayback().playing=false;brushFeedback_.brushPreviewShift_=false;

    currentTools().pencilImageBrush.reset();currentTools().brushProfiles[0]={3,50,BrushShape::Square};ink_=0xff0000ff;fitCanvas();refresh();

    auto point=[&](int x,int y){return gfx::Point(currentView().canvas.x+int((x+.5)*canvasScale()),currentView().canvas.y+int((y+.5)*canvasScale()));};

    auto render=[&](){auto image=os::instance()->makeRgbaSurface(bounds().w,bounds().h);ui::Graphics g(image);ensureContentCache();paintCanvas(g);return image;};

    auto same=[](const os::SurfaceRef& a,const os::SurfaceRef& b){for(int y=0;y<a->height();++y)for(int x=0;x<a->width();++x)if(a->getPixel(x,y)!=b->getPixel(x,y))return false;return true;};

    updatePaletteMouse({});auto base=render();const auto uploads=renderer_.uploads();const auto history=currentDocument().historySize(),revision=currentDocument().contentRevision();const auto pixels=currentDocument().pixels();

    if(!canvasOwnsPointer(point(6,5)))throw std::runtime_error("Brush preview fixture pointer is occluded");
    updatePaletteMouse(point(6,5));auto preview=render();if(same(base,preview) || currentDocument().pixels()!=pixels || currentDocument().historySize()!=history || currentDocument().contentRevision()!=revision || currentDocument().dirty() || renderer_.uploads()!=uploads)throw std::runtime_error("Hover preview missing or mutates document/cache");

    runtimePreferences_.set("cursor.brushPreviewMode.Select","0");if(!same(base,render()))throw std::runtime_error("Brush preview None ignored");

    runtimePreferences_.set("cursor.brushPreviewMode.Select","1");auto edge=render();if(same(base,edge) || same(preview,edge))throw std::runtime_error("Brush edge mode ignored");

    runtimePreferences_.set("cursor.brushPreviewMode.Select","3");auto fullEdge=render();if(same(preview,fullEdge) || same(edge,fullEdge))throw std::runtime_error("Full plus edge preview ignored");

    runtimePreferences_.set("cursor.brushPreviewMode.Select","2");

    writeSmokeFrame(preview.get(),std::filesystem::path("build")/"brush-preview-smoke.bmp");

    updatePaletteMouse({});if(!same(base,render()))throw std::runtime_error("Preview leaves a trail on pointer exit");

    updatePaletteMouse(point(6,5));spaceHeld_=true;if(!same(base,render()))throw std::runtime_error("Pan did not suppress preview");spaceHeld_=false;

    eyedropperHeld_=true;if(!same(base,render()))throw std::runtime_error("Sampling did not suppress preview");eyedropperHeld_=false;

    currentDocument().beginStroke({6,5},ink_,currentTools().brushProfiles[0]);runtimePreferences_.set("cursor.drawingBrushPreviewEnabled","false");auto drawing=render();updatePaletteMouse({});if(!same(drawing,render()))throw std::runtime_error("Drawing pencil overlays translucent paint twice");runtimePreferences_.set("cursor.drawingBrushPreviewEnabled","true");updatePaletteMouse(point(6,5));if(same(drawing,render()))throw std::runtime_error("Drawing brush edge preference ignored");currentDocument().cancelStroke();

    currentTools().eraser=true;currentTools().brushProfiles[1]={3,100,BrushShape::Round};updatePaletteMouse(point(0,0));if(same(base,render()))throw std::runtime_error("Eraser outline missing at canvas edge");currentTools().eraser=false;

    brushFeedback_.brushPreviewShift_=true;brushFeedback_.brushLineAnchors_[0]=BrushLineAnchor{{2,2},currentDocument().identity(),currentDocument().revision(),currentDocument().layer().id,currentDocument().frame().id,{},false};updatePaletteMouse(point(12,7));auto line=render();brushFeedback_.brushPreviewShift_=false;if(same(line,render()))throw std::runtime_error("Shift connected line preview missing");

    brushFeedback_.brushLineAnchors_[0].reset();updatePaletteMouse({});

  }

void Editor::smokeBrushPreviewPerformance(){

    smokeBrushPreview();replaceDocumentForSmoke(Document(256,256));fitCanvas();refresh();ensureContentCache();

    const auto directory=std::filesystem::path("build")/"test-tmp";std::filesystem::create_directories(directory);

    std::ofstream report(directory/"brush-preview-performance.txt");

    auto point=[&](int x,int y){return gfx::Point(currentView().canvas.x+int((x+.5)*canvasScale()),currentView().canvas.y+int((y+.5)*canvasScale()));};

    auto paint=[&](os::SurfaceRef surface,gfx::Rect clip){if(clip.isEmpty())return;ui::Graphics g(surface);g.saveClip();g.clipRect(clip);paintCanvas(g);g.restoreClip();};

    auto full=os::instance()->makeRgbaSurface(bounds().w,bounds().h),local=os::instance()->makeRgbaSurface(bounds().w,bounds().h);

    auto verify=[&](const char* name){

      paletteMousePosition_.reset();full->clear();local->clear();paint(full,canvasViewport());paint(local,canvasViewport());

      for(auto position:std::vector<std::optional<gfx::Point>>{point(100,100),point(101,100),point(170,140),point(0,0),point(255,255),{}}){

        const auto old=brushPreviewDamage(paletteMousePosition_);paletteMousePosition_=position;const auto next=brushPreviewDamage(position);

        brushFeedback_.brushPreviewBatch_=true;paint(local,old);paint(local,next);brushFeedback_.brushPreviewBatch_=false;paint(full,canvasViewport());brushFeedback_.brushPreviewBatch_=true;

        for(int y=0;y<bounds().h;++y)for(int x=0;x<bounds().w;++x)if(full->getPixel(x,y)!=local->getPixel(x,y))throw std::runtime_error(std::string("Partial brush repaint mismatch: ")+name+" at "+std::to_string(x)+","+std::to_string(y)+" full="+std::to_string(full->getPixel(x,y))+" local="+std::to_string(local->getPixel(x,y))+" next="+std::to_string(next.x)+","+std::to_string(next.y)+","+std::to_string(next.w)+","+std::to_string(next.h));

      }

    };

    const auto uploads=renderer_.uploads();const auto revision=currentDocument().contentRevision();const auto history=currentDocument().historySize();

    for(bool erase:{false,true})for(int size:{1,16,64}){

      currentTools().eraser=erase;currentTools().brushProfiles[erase?1:0]={size,50,BrushShape::Round};

      verify(erase?"eraser":"pencil");

      double elapsed[2]{};std::uint64_t area[2]{};

      for(int mode=0;mode<2;++mode){brushFeedback_.brushPreviewBatch_=mode!=0;paletteMousePosition_=point(100,100);paint(local,canvasViewport());

        const auto start=std::chrono::steady_clock::now();

        for(int i=0;i<120;++i){const auto old=brushPreviewDamage(paletteMousePosition_);paletteMousePosition_=point(100+i%30,100+i%7);const auto next=brushPreviewDamage(paletteMousePosition_);

          if(!mode){paint(local,canvasViewport());area[mode]+=std::uint64_t(canvasViewport().w)*canvasViewport().h;}

          else{const auto combined=old|next;paint(local,combined);area[mode]+=std::uint64_t(combined.w)*combined.h;}

        }

        elapsed[mode]=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count()/120;

      }

      report<<(erase?"eraser":"pencil")<<" size="<<size<<" full_ms="<<elapsed[0]<<" partial_ms="<<elapsed[1]<<" full_pixels="<<area[0]/120<<" partial_pixels="<<area[1]/120<<std::endl;

    }

    currentTools().eraser=true;for(auto shape:{BrushShape::Square,BrushShape::Line})for(int size:{2,3,64}){currentTools().brushProfiles[1]={size,100,shape};verify("eraser boundary cache");}

    currentTools().eraser=false;currentTools().brushProfiles[0]={16,50,BrushShape::Square};

    for(double scale:{.25,1.5,8.0}){setCanvasZoom(canvasViewport().center(),scale);verify("fractional zoom");}

    fitCanvas();

    PatternBrush image;image.width=11;image.height=5;image.coverage.assign(55,255);image.colors.assign(55,0x80123456);currentTools().pencilImageBrush=image;currentTools().pencilImageBrushAngle=37;

    verify("rotated image");currentTools().eraser=true;verify("image eraser");currentTools().eraser=false;currentTools().pencilImageBrush.reset();

    brushFeedback_.brushPreviewShift_=true;brushFeedback_.brushLineAnchors_[0]=BrushLineAnchor{{2,2},currentDocument().identity(),currentDocument().revision(),currentDocument().layer().id,currentDocument().frame().id,{},false};verify("connected line");brushFeedback_.brushPreviewShift_=false;brushFeedback_.brushLineAnchors_[0].reset();

    currentDocument().symmetryAxes.horizontal=true;verify("symmetry");currentDocument().symmetryAxes={};

    if(currentDocument().contentRevision()!=revision || currentDocument().historySize()!=history || currentDocument().dirty() || renderer_.uploads()!=uploads)throw std::runtime_error("Hover performance replay mutated document/cache");

    std::vector<Pixel> backdrop(256*256);for(std::size_t i=0;i<backdrop.size();++i)backdrop[i]=Pixel(i%256)<<24|0x7031c9;

    replaceDocumentForSmoke(Document::fromImage(256,256,std::move(backdrop),U"preview alpha fixture"));currentDocument().addLayer();refresh();ensureContentCache();

    image.width=16;image.height=16;image.coverage.assign(256,255);image.colors.resize(256);for(int i=0;i<256;++i)image.colors[i]=Pixel(i)<<24|0x34a9e3;

    currentTools().pencilImageBrush=image;currentTools().pencilImageBrushAngle=0;verify("all alpha multi-layer image");currentTools().pencilImageBrush.reset();

    // Exercise the actual invalidation path as well as the framebuffer oracle.

    manager()->dispatchMessages();updatePaletteMouse(point(100,100));manager()->dispatchMessages();updatePaletteMouse(point(101,100));

    if(!getUpdateRegion().contains(point(101,100)) || getUpdateRegion().bounds().w>=canvasViewport().w || getUpdateRegion().bounds().h>=canvasViewport().h)throw std::runtime_error("Hover damage is empty or still invalidates full canvas");

    updatePaletteMouse({});report<<"pixel_equivalence=pass\n";

  }

void Editor::smokeModifierBrushPerformance(){

    smoke_=true;homeOpen_=false;documentOpen_=true;pending_=Pending::None;currentPlayback().playing=false;

    currentTools().selectionTool=currentTools().shapeTool=currentTools().gradientTool=currentTools().fillTool=currentTools().handTool=currentTools().zoomTool=currentTools().eyedropperTool=currentTools().eraser=spaceHeld_=eyedropperHeld_=false;

    currentTools().pencilImageBrush.reset();paletteMousePosition_.reset();replaceDocumentForSmoke(Document(256,256));fitCanvas();refresh();

    auto drain=[&]{manager()->flushRedraw();manager()->dispatchMessages();};drain();invalidate();drain();

    std::filesystem::create_directories("build/test-tmp");std::ofstream report("build/test-tmp/modifier-brush-performance.txt");

    auto require=[](bool ok,const char* text){if(!ok)throw std::runtime_error(text);};

    const auto ca=ui::KeyModifiers(ui::kKeyCtrlModifier|ui::kKeyAltModifier);

    const auto origin=canvasViewport().center();

    auto move=[&](gfx::Point at,ui::KeyModifiers mods){updatePaletteMouse(at);ui::MouseMessage m(ui::kMouseMoveMessage,os::PointerType::Mouse,ui::kButtonNone,mods,at);onProcessMessage(&m);};

    auto wheel=[&](int delta){updatePaletteMouse(origin);ui::MouseMessage m(ui::kMouseWheelMessage,os::PointerType::Mouse,ui::kButtonNone,ui::kKeyCtrlModifier,origin,gfx::Point(0,delta));onProcessMessage(&m);};

    auto pixels=[&]{auto surface=display()->nativeWindow()->surface();os::SurfaceLock lock(surface);std::vector<gfx::Color> result;result.reserve(surface->width()*surface->height());for(int y=0;y<surface->height();++y)for(int x=0;x<surface->width();++x)result.push_back(surface->getPixel(x,y));return result;};

    const auto revision=currentDocument().contentRevision(),history=currentDocument().historySize();const auto uploads=renderer_.uploads();const auto zoom=currentView().zoom;

    for(bool erase:{false,true})for(bool dragging:{false,true}){

      currentTools().eraser=erase;

      for(int baseline=1;baseline>=0;--baseline){

        finishModifierBrushSize();currentTools().brushProfiles[erase?1:0]={16,50,BrushShape::Round};layoutToolOptions();updatePaletteMouse(origin);invalidate();drain();

        if(dragging){move(origin,ca);drain();}

        const auto layouts=brushFeedback_.toolOptionsLayouts_,chrome=chromePaints_,writes=brushFeedback_.brushPreferenceWrites_;

        const auto start=std::chrono::steady_clock::now();

        for(int i=0;i<20;++i){

          if(dragging)move(origin+gfx::Point((i%2?0:8)*4*uiScale,i%3),ca);else wheel(i%2?1:-1);

          if(baseline){layoutToolOptions();invalidateRect(canvasViewport());}drain();

        }

        report<<(erase?"eraser":"pencil")<<" input="<<(dragging?"ctrl_alt_move":"ctrl_wheel")<<" mode="<<(baseline?"full":"local")<<" mean_ms="<<std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count()/20<<" layouts="<<brushFeedback_.toolOptionsLayouts_-layouts<<" chrome_paints="<<chromePaints_-chrome<<std::endl;

        if(!baseline){require(brushFeedback_.toolOptionsLayouts_==layouts,"Modifier resize still lays out toolbar");require(chromePaints_==chrome,"Modifier resize repainted unrelated chrome");}

        require(brushFeedback_.brushPreferenceWrites_==writes,"Modifier input wrote preferences synchronously");

        // Flush must persist the final model once, including no-keyup wheel bursts.

        flushBrushSizePreferences();require(brushFeedback_.brushPreferenceWrites_==writes+1 && !brushFeedback_.brushPreferencesPending_,"Resize burst did not flush exactly once");flushBrushSizePreferences();require(brushFeedback_.brushPreferenceWrites_==writes+1,"Resize burst flushed twice");

        finishModifierBrushSize();

      }

      // Compare native framebuffer after actual events with a forced full redraw.

      for(int size:{1,64,2,32,1}){

        if(dragging){finishModifierBrushSize();currentTools().brushProfiles[erase?1:0].size=size==64?63:size+1;layoutToolOptions();updatePaletteMouse(origin);invalidate();drain();move(origin,ca);move(origin+gfx::Point((size-currentTools().brushProfiles[erase?1:0].size)*4*uiScale,0),ca);require(currentTools().brushProfiles[erase?1:0].size==size,"Pointer resize target mismatch");}

        else {while(currentTools().brushProfiles[erase?1:0].size!=size)wheel(currentTools().brushProfiles[erase?1:0].size<size?-1:1);}

        drain();const auto local=pixels();invalidate();drain();require(local==pixels(),"Modifier resize leaves stale pixels or toolbar differs from full repaint");finishModifierBrushSize();

      }

    }

    // Shape changes at size 1 retain the selection brush angle field semantics.

    currentTools().eraser=false;currentTools().selectionTool=true;currentTools().selectionKind=5;selectionPropertiesActive_=false;toolRowScroll_=0;currentTools().brushProfiles[0]={1,100,BrushShape::Square};layoutToolOptions();setModifierBrushSize(2);toolRowScroll_=selectionBrushAngleInput_->bounds().x-canvasViewport().x;layoutToolOptions();require(selectionBrushAngleInput_->isVisible(),"Selection brush angle was not revealed after scrolling into view");setModifierBrushSize(1);require(!selectionBrushAngleInput_->isVisible(),"Selection brush angle was not hidden");currentTools().selectionTool=false;

    currentTools().brushProfiles[0].size=64;flushBrushSizePreferences();const auto writes=brushFeedback_.brushPreferenceWrites_;wheel(-1);require(!brushFeedback_.brushPreferencesPending_ && brushFeedback_.brushPreferenceWrites_==writes,"Clamped wheel schedules a redundant write");

    require(currentDocument().contentRevision()==revision && currentDocument().historySize()==history && !currentDocument().dirty() && renderer_.uploads()==uploads && currentView().zoom==zoom,"Modifier sizing changed artwork, upload or zoom");

    report<<"native_framebuffer_equivalence=pass\nmodel_and_persistence=pass\n";flushBrushSizePreferences();

  }

