    navigation_.zoomSmooth_=false;pointer(ui::kMouseDownMessage,ui::kButtonLeft,anchor);pointer(ui::kMouseMoveMessage,ui::kButtonLeft,anchor+gfx::Point(48*uiScale,0));require(currentView().zoom==nextCanvasScale(nextCanvasScale(start,1),1));pointer(ui::kMouseMoveMessage,ui::kButtonLeft,anchor);require(currentView().zoom==start);pointer(ui::kMouseUpMessage,ui::kButtonLeft,anchor+gfx::Point(0,4*uiScale));require(currentView().zoom==start);

    require(canvasZoomDragTarget(8,23,false,false)==8 && canvasZoomDragTarget(8,-24,false,false)==6 && canvasZoomDragTarget(8,96,true,false)==16 && canvasZoomDragTarget(8,23,true,true)==8);

