    ui::KeyMessage zoom(ui::kKeyDownMessage,ui::kKeyZ,ui::kKeyNoneModifier,0,0);onProcessMessage(&zoom);require(currentTools().zoomTool);

    pointer(ui::kMouseDownMessage,ui::kButtonLeft,anchor);ui::KeyMessage escape(ui::kKeyDownMessage,ui::kKeyEsc,ui::kKeyNoneModifier,0,0);onProcessMessage(&escape);require(!navigation_.zoomDragging_);

